from __future__ import annotations

import argparse
import sys
import tomllib
from pathlib import Path
from typing import Any

__version__ = "0.1.0"

STRICT_SELECT = ["E", "F", "B", "I"]


# ---------------------------------------------------------------- serializer


def _format_value(value: Any) -> str:
    """Format a TOML scalar or array-of-scalars value."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'
    if isinstance(value, list):
        return "[" + ", ".join(_format_value(v) for v in value) + "]"
    raise TypeError(f"unsupported TOML value type: {type(value).__name__}")


def _is_table(value: Any) -> bool:
    return isinstance(value, dict)


def dumps(data: dict[str, Any]) -> str:
    """Serialize a dict as TOML. Tables are emitted after their siblings'
    scalar/array keys; nested tables use dotted headers ([a.b])."""
    lines: list[str] = []

    def emit(table: dict[str, Any], prefix: str) -> None:
        scalars = {k: v for k, v in table.items() if not _is_table(v)}
        subtables = {k: v for k, v in table.items() if _is_table(v)}

        if prefix and (scalars or not subtables):
            header = f"[{prefix}]"
            if lines:
                lines.append("")
            lines.append(header)
        for key, value in scalars.items():
            lines.append(f"{key} = {_format_value(value)}")
        for key, value in subtables.items():
            emit(value, f"{prefix}.{key}" if prefix else key)

    emit(data, "")
    return "\n".join(lines) + "\n"


# ------------------------------------------------------------------- config


def build_config(line_length: int, target: str, strict: bool) -> dict[str, Any]:
    tool: dict[str, Any] = {
        "black": {
            "line-length": line_length,
            "target-version": [target],
        },
        "ruff": {
            "line-length": line_length,
            "target-version": target,
        },
    }
    if strict:
        tool["ruff"]["select"] = list(STRICT_SELECT)
    return {"tool": tool}


def merge(existing: dict[str, Any], config: dict[str, Any]) -> dict[str, Any]:
    """Deep-merge config into existing; existing keys win only where config
    doesn't touch them. lintconf's own keys are overwritten."""
    result = {**existing}
    for key, value in config.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = value
    return result


# ---------------------------------------------------------------------- CLI


def cmd_init(args: argparse.Namespace) -> int:
    path = Path(args.file)
    config = build_config(args.line_length, args.target, args.strict)

    if path.exists():
        with open(path, "rb") as fh:
            try:
                existing = tomllib.load(fh)
            except tomllib.TOMLDecodeError as exc:
                print(f"error: {path} is not valid TOML: {exc}", file=sys.stderr)
                return 1
        merged = merge(existing, config)
        action = "updated"
    else:
        merged = config
        action = "created"

    path.write_text(dumps(merged), encoding="utf-8")
    print(f"{action} {path}")
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="lintconf", description=__doc__)
    parser.add_argument("--version", action="version", version=__version__)
    sub = parser.add_subparsers(dest="command", required=True)

    init = sub.add_parser("init", help="write [tool.ruff]/[tool.black] to pyproject.toml")
    init.add_argument("--line-length", type=int, default=88, help="max line length (default: 88)")
    init.add_argument("--target", default="py311", help="python target, e.g. py311 (default: py311)")
    init.add_argument("--strict", action="store_true", help='enable ruff select = ["E", "F", "B", "I"]')
    init.add_argument("--file", default="pyproject.toml", help="target file (default: pyproject.toml)")
    init.set_defaults(func=cmd_init)
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    raise SystemExit(main())
